pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e20);

        // owner is the deployer (this test contract). Fund the owner and donate via the payable fallback.
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok, "donation failed");
        assertEq(address(c).balance, amount);

        // owner drains the contract via withdrawAll
        vm.prank(address(this));
        c.withdrawAll();

        // reference: the full balance is withdrawn; mutant withdraws 0 and balance stays positive
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}

