pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // give the contract a base balance via fallback
        vm.deal(address(this), 10 ether);
        (bool s,) = address(c).call{value: 10 ether}("x");
        s;
    }

    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(uint256(uint160(caller)) != uint256(uint160(address(this))));
        amount = bound(amount, 1, 5 ether); // strictly less than the 10 ether balance
        address owner = c.owner();
        uint256 before = address(c).balance;
        vm.deal(owner, 1);
        vm.prank(owner);
        c.withdraw(amount);
        assertEq(address(c).balance, before - amount);
    }
}

