pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 2, type(uint256).max - 1);
        // contract holds exactly amount - 1 > 0, less than the requested amount
        vm.deal(address(c), amount - 1);
        vm.prank(address(this)); // owner is the test contract (deployer)
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        // reference P: transfer(amount) exceeds balance -> must fail
        // mutant M: drains whole balance (amount-1 > 0) -> succeeds
        assertTrue(!ok, "withdraw beyond balance must revert");
    }
}

