pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 value) public {
        // wide admissible domain: fund c with a positive amount, request at most that amount
        amount = bound(amount, 1, 1 ether);
        value = bound(value, 0, amount - 1); // value < amount, so a correct partial withdrawal keeps > 0

        vm.deal(address(c), amount);
        vm.deal(address(this), value); // c's owner is address(this); onlyOwner passes

        c.withdraw(value);

        // Rule: partial withdrawal leaves exactly amount - value (nonzero since value < amount)
        assertTrue(address(c).balance == amount - value && address(c).balance > 0);
    }
}

