pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 value) public {
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(address(c), amount);
        uint256 balance0 = address(c).balance;
        value = bound(value, 0, balance0);
        try c.withdraw(value) {
            assertEq(address(c).balance, balance0 - value);
        } catch {
            // a revert is admissible only if it reverts for both versions identically;
            // the reference only reverts when value > balance, which is excluded by bound
            assertTrue(false);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // accept ETH transferred back by c.withdraw (transfer target is msg.sender == owner == this)
    receive() external payable {}

    function testFuzz_property(uint256 fund, uint256 value) public {
        // admissible domain: fund the contract with a positive amount, request a strict partial withdrawal
        fund = bound(fund, 1, 1e30);
        value = bound(value, 1, fund - 1); // 0 < value < fund, so the reference can pay and keeps a remainder

        // fund the test contract (owner) so it can send ETH into c via fallback
        vm.deal(address(this), fund);
        (bool okPay,) = address(c).call{value: fund}("");
        assertTrue(okPay);

        uint256 before = address(c).balance;
        assertEq(before, fund);

        // owner (the test contract) drives the withdraw entry point
        c.withdraw(value);

        // GENERAL RULE: partial withdrawal of value leaves exactly fund - value in the contract.
        // The mutant drains the entire balance, so it leaves 0 whenever 0 < value < fund.
        assertTrue(address(c).balance == fund - value);
    }
}

