pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address target, bytes memory data) public {
        vm.assume(target != address(c) && target != address(this));
        vm.deal(address(c), 100 ether);
        amount = bound(amount, 1, 50 ether);
        data = bytes(data);
        if (data.length > 0) {
            data[0] = 0x00; // avoid function-selector on plain EOAs; call still succeeds
        }

        uint256 before = address(c).balance;
        bool ok;
        (bool sent, ) = address(c).call(
            abi.encodeWithSelector(c.sendMoney.selector, target, amount, data)
        );
        ok = sent;

        uint256 afterBal = address(c).balance;
        assertTrue(!ok || (before - afterBal == amount), "sendMoney must send exactly value");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNonOwnerBlocked() public {
        // The test contract is not the owner of c (owner is whoever deployed C).
        // In P, withdrawAll reverts for a non-owner; in M it succeeds.
        bool ok;
        bytes memory ret;
        (ok, ret) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        assert(!ok);
    }
}

