        // A non-owner must not be able to withdraw; P's onlyOwner reverts, M does not.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

